export function getTranslatedLiuGongSparePartName(partName: string, language: string): string {
  const translations = liugongNameTranslations[partName];
  return translations ? (translations[language] || partName) : partName;
}

export function getTranslatedLiuGongSparePartCategory(category: string, language: string): string {
  const translations = liugongCategoryTranslations[category];
  return translations ? (translations[language] || category) : category;
}

export function getTranslatedLiuGongSparePartDescription(partName: string, language: string): string {
  const translations = liugongDescriptionTranslations[partName];
  return translations ? (translations[language] || partName) : partName;
}
